{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count for a parsed election. Returns
 * `{ rounds, winner }` where each round is
 * `{ votes: Map<name, count>, exhausted, eliminated }`, `eliminated` being
 * the eliminated candidate's name or `null`, and `winner` is the winning
 * candidate's name or `null` when nobody wins.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null
  const totalCount = ballots.reduce((s, b) => s + b.count, 0)

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    let activeTotal = 0

    for (const b of ballots) {
      const target = b.names.find((n) => continuing.has(n))
      if (target !== undefined) {
        votes.set(target, votes.get(target) + b.count)
        activeTotal += b.count
      }
    }

    const exhausted = totalCount - activeTotal
    history.push(votes)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let roundWinner = null
    for (const [name, v] of votes) {
      if (v * 2 > activeTotal) {
        roundWinner = name
        break
      }
    }

    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    let minV = Infinity
    for (const v of votes.values()) if (v < minV) minV = v
    const tied = [...continuing].filter((c) => votes.get(c) === minV)
    const eliminated = tiebreak(tied, history)

    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function tiebreak(tiedInit, history) {
  let tied = tiedInit
  if (tied.length === 1) return tied[0]

  while (true) {
    let splitFound = false
    for (const votesMap of history) {
      const vals = tied.map((c) => votesMap.get(c))
      const allEqual = vals.every((v) => v === vals[0])
      if (!allEqual) {
        const minV = Math.min(...vals)
        tied = tied.filter((c) => votesMap.get(c) === minV)
        splitFound = true
        break
      }
    }
    if (!splitFound || tied.length === 1) break
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((a, b) => (a > b ? a : b))
}
"}

