{"file_path":"src/format.js","content":"/**
 * Formats one round's `round K: ...` line, listing continuing candidates by
 * descending vote count, and by ascending name where counts tie.
 */
export function formatRoundLine(roundNum, votes, exhausted) {
  const entries = [...votes.entries()]
  entries.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const parts = entries.map(([name, v]) => `${name}=${v}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNum}: ${parts.join(' ')}`
}

/** Formats the final `winner <name>` or `no winner` line. */
export function formatWinnerLine(winner) {
  return winner !== null ? `winner ${winner}` : 'no winner'
}
"}

