  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ElectionError) {
      const prefix = err.line !== undefined ? `line ${err.line}: ` : ''
      process.stderr.write(`error: ${prefix}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

